node -e "
const fs=require('fs');
let killed=0;
for(const pid of fs.readdirSync('/proc').filter(d=>/^\d+\$/.test(d))){
  let cmd='';
  try{cmd=fs.readFileSync('/proc/'+pid+'/cmdline','utf8').replace(/\0/g,' ')}catch{continue}
  if(cmd.includes('3123')&&!cmd.includes('-e')){
    console.log('killing',pid,cmd.trim());
    try{process.kill(Number(pid),'SIGKILL');killed++}catch(e){console.log(e.message)}
  }
}
if(!killed)console.log('nothing matched');
"; sleep 1; node -e "fetch('http://localhost:3123/').then(()=>console.log('STILL UP')).catch(()=>console.log('port 3123 closed'))"

